#!/usr/bin/env python3
import json, sys
from pathlib import Path
REQUIRED=["SKILL.md","README.md","contracts/main_contract.md","contracts/missing_input_policy.md","schemas/output.schema.json","schemas/missing_input.schema.json","judges/score_rubric.md","judges/mini_judge.md","checklists/preflight_checklist.md","checklists/priority_checklist.md","examples/good_output.json","examples/bad_output.json","examples/self_repair_output.json","fixtures/happy_path/input.json","fixtures/missing_inputs/input.json","fixtures/unsafe_or_blocked/input.json","fixtures/unsupported_rule/input.json","fixtures/internal_leakage/input.json","fixtures/off_scope/input.json","evals/eval_matrix.json","handoffs/to_quality_pack.handoff.json","adapters/github_pack_adapter.md","manifest.json","validators/validate_pack.py"]
STATUSES={"INTERFACE_DECISION_READY","RETURN_TO_ORCHESTRATOR","RETURN_TO_WORKER_FOR_SELF_REPAIR","BLOCK_PIPELINE"}
FORBIDDEN_USER_KEYS={"next_gate","blocking_codes","source_authority","github","supabase","sandbox","pass","score"}
def load(p): return json.loads(p.read_text(encoding="utf-8"))
def main():
    root=Path(sys.argv[1]) if len(sys.argv)>1 else Path.cwd()
    blocking=[]
    for rel in REQUIRED:
        if not (root/rel).exists(): blocking.append("MISSING_REQUIRED_FILE:"+rel)
    if not blocking:
        try:
            m=load(root/"manifest.json")
            if m.get("profile_pack_id")!="PROFILE_UI_INTERFACE_ARCHITECT_LF_V0_2": blocking.append("MANIFEST_PACK_ID_MISMATCH")
            if m.get("document_status")!="CANDIDATO": blocking.append("DOCUMENT_STATUS_MUST_BE_CANDIDATO")
            if m.get("operational_status")!="READ_ONLY": blocking.append("OPERATIONAL_STATUS_MUST_BE_READ_ONLY")
            if m.get("runtime")!="NO_HABILITADO": blocking.append("RUNTIME_MUST_BE_NO_HABILITADO")
            if m.get("automatic_impact")!="BLOQUEADO": blocking.append("AUTOMATIC_IMPACT_MUST_BE_BLOQUEADO")
            declared=set(m.get("files",[]))
            for rel in REQUIRED:
                if rel not in declared: blocking.append("MANIFEST_MISSING_DECLARATION:"+rel)
            schema=load(root/"schemas/output.schema.json")
            if set(schema.get("required",[]))!={"status","decision_id","user_payload","evidence_map","internal_envelope"}: blocking.append("OUTPUT_SCHEMA_REQUIRED_FIELDS_MISMATCH")
            props=schema.get("properties",{})
            if "user_payload" not in props or "internal_envelope" not in props: blocking.append("OUTPUT_SCHEMA_MISSING_PAYLOAD_BOUNDARY")
            good=load(root/"examples/good_output.json"); bad=load(root/"examples/bad_output.json"); repair=load(root/"examples/self_repair_output.json")
            for name,obj in [("good",good),("bad",bad),("repair",repair)]:
                if obj.get("status") not in STATUSES: blocking.append("INVALID_EXAMPLE_STATUS:"+name)
                for key in ["decision_id","user_payload","evidence_map","internal_envelope"]:
                    if key not in obj: blocking.append("EXAMPLE_MISSING_FIELD:"+name+":"+key)
            if not good.get("evidence_map"): blocking.append("GOOD_EXAMPLE_EVIDENCE_REQUIRED")
            user_blob=json.dumps(good.get("user_payload",{})).lower()
            for key in FORBIDDEN_USER_KEYS:
                if f'"{key}"' in user_blob: blocking.append("GOOD_EXAMPLE_INTERNAL_METADATA_LEAK:"+key)
            if bad.get("status")!="BLOCK_PIPELINE": blocking.append("BAD_EXAMPLE_MUST_BLOCK")
            if "LF_SAFETY_HARD_FAIL" not in bad.get("internal_envelope",{}).get("blocking_codes",[]): blocking.append("BAD_EXAMPLE_MISSING_LF_SAFETY_BLOCK")
            if repair.get("status")!="RETURN_TO_WORKER_FOR_SELF_REPAIR": blocking.append("SELF_REPAIR_EXAMPLE_STATUS_INVALID")
            matrix=load(root/"evals/eval_matrix.json"); cases=matrix.get("cases",[])
            if len(cases)<6: blocking.append("EVAL_MATRIX_REQUIRES_MINIMUM_6_CASES")
            ids=set()
            for case in cases:
                cid=case.get("id")
                if not cid or cid in ids: blocking.append("EVAL_CASE_ID_INVALID")
                ids.add(cid)
                fixture=case.get("fixture")
                if not fixture or not (root/fixture).exists(): blocking.append("EVAL_FIXTURE_MISSING:"+str(fixture))
                if case.get("expected_status") not in STATUSES: blocking.append("EVAL_EXPECTED_STATUS_INVALID:"+str(cid))
                if not isinstance(case.get("assertions"),list) or not case.get("assertions"): blocking.append("EVAL_ASSERTIONS_REQUIRED:"+str(cid))
            handoff=load(root/"handoffs/to_quality_pack.handoff.json"); req=set(handoff.get("required_receiver_context",[]))
            for key in ["artifact_ref","main_contract_ref","output_schema_ref","evidence_map","score_rubric_ref","mini_judge_ref","blocking_codes","remaining_risks"]:
                if key not in req: blocking.append("HANDOFF_CONTEXT_MISSING:"+key)
            if handoff.get("next_gate")!="SEMANTIC_QUALITY_REVIEW": blocking.append("HANDOFF_NEXT_GATE_INVALID")
            contract=(root/"contracts/main_contract.md").read_text(encoding="utf-8").lower()
            for marker in ["user_payload","internal_envelope","fake urgency","guaranteed","source"]:
                if marker not in contract: blocking.append("CONTRACT_REQUIRED_CONTROL_MISSING:"+marker)
            src=(root/"validators/validate_pack.py").read_text(encoding="utf-8")
            unconditional = "print" + "(" + chr(39) + "STRUCTURAL_PASS" + chr(39) + ")"
            unconditional2 = "print" + "(" + chr(34) + "STRUCTURAL_PASS" + chr(34) + ")"
            executable_lines = [line.strip() for line in src.splitlines() if line.strip() and not line.lstrip().startswith("#")]
            if unconditional in executable_lines or unconditional2 in executable_lines:
                blocking.append("VALIDATOR_UNCONDITIONAL_STRUCTURAL_PASS")
        except Exception as exc: blocking.append("VALIDATION_EXCEPTION:"+str(exc))
    result={"status":"PASS" if not blocking else "FAIL","profile_pack_id":"PROFILE_UI_INTERFACE_ARCHITECT_LF_V0_2","validation_scope":"STRUCTURAL_SEMANTIC_GUARDRAILS_ONLY","semantic_quality_review":"NOT_EXECUTED","blocking_codes":blocking,"runtime_authorized":False,"automatic_impact_authorized":False,"recommended_action":"INDEPENDENT_SEMANTIC_QUALITY_REVIEW" if not blocking else "RETURN_TO_WORKER_FOR_SELF_REPAIR"}
    print(json.dumps(result,indent=2))
    return 0 if not blocking else 1
if __name__=="__main__": raise SystemExit(main())
